1	package world
2	
3	import "errors"
4	
5	// RecoveryPreview 是一次恢复预览的结果。
6	//
7	// 预览只读：返回槽当前指向的记录标识、按本槽保存生效次序选中的来源记录
8	// 标识，以及来源记录的完整世界状态（深拷贝）。它不改变槽指向、历史或
9	// 任何记录文件。
10	type RecoveryPreview struct {
11		// Current 是槽指针当前指向的记录标识。它可能已损坏或被删除，
12		// 但仍是之后确认恢复时必须一致的“当前标识”。
13		Current RecordID
14		// Source 是选中的来源记录标识：本槽保存次序最近一份校验通过且
15		// 版本可接受的记录。它可能与 Current 相同（当前记录本就可读）。
16		Source RecordID
17		// State 是来源记录保存时的完整世界状态（深拷贝，修改不影响存档）。
18		State State
19	}
20	
21	// PreviewRecovery 预览将恢复的内容而不改写存档。
22	//
23	// 传入槽名与调用方可接受的规则版本集合，返回槽当前指向的记录标识、选中
24	// 的来源记录标识及其完整世界状态。来源按本槽“保存生效次序”选择最近一份
25	// 内容与父关系校验通过且版本可接受的记录，越过缺失、截断、校验失败与
26	// 版本不被接受的记录；分支只在分支自身的历史中选择，不跨入来源槽。当前
27	// 记录本就完好且版本可接受时可以选中它本身。
28	//
29	// 槽不存在返回 *NotFoundError；槽指针无法解析返回 *CorruptError（即使其
30	// 指向的记录已损坏或被删除，也仍会返回该当前标识用于预览）；槽中没有
31	// 任何可用记录时返回包装了 ErrUnrecoverable 的 *UnrecoverableError。
32	// 预览绝不写入、修补或删除任何数据，可重复调用。
33	func (a *Archive) PreviewRecovery(slot string, acceptedVersions []string) (RecoveryPreview, error) {
34		if !validSlotName(slot) {
35			return RecoveryPreview{}, &NotFoundError{Slot: slot}
36		}
37		lock, err := acquireSharedLock(a.dir)
38		if err != nil {
39			return RecoveryPreview{}, err
40		}
41		defer lock.release()
42		return a.previewRecoveryLocked(slot, acceptedVersions)
43	}
44	
45	// previewRecoveryLocked 在调用方已持锁（共享或排他均可）的前提下执行预览。
46	func (a *Archive) previewRecoveryLocked(slot string, acceptedVersions []string) (RecoveryPreview, error) {
47		pointer, err := a.readSlotPointerLocked(slot)
48		if err != nil {
49			return RecoveryPreview{}, err
50		}
51		// slotHistoryLocked 以指针当前指向为链头，并负责旧格式裸指针沿可信
52		// 父链的重建；当前记录损坏或缺失只会让重建停在那里，不妨碍指针内嵌
53		// 历史索引中更早的本槽记录成为候选。
54		history, err := a.slotHistoryLocked(slot)
55		if err != nil {
56			return RecoveryPreview{}, err
57		}
58		env, err := a.firstRecoverableLocked(history, acceptedVersions)
59		if err != nil {
60			var ue *UnrecoverableError
61			if errors.As(err, &ue) {
62				ue.Slot = slot
63			}
64			return RecoveryPreview{}, err
65		}
66		return RecoveryPreview{
67			Current: pointer.Latest,
68			Source:  env.ID,
69			State:   cloneState(env.State),
70		}, nil
71	}
72	
73	// ConfirmRecovery 把预览选中的来源记录正式保存回本槽并继续使用。
74	//
75	// 入参为槽名、预览返回的当前记录标识 current 与来源记录标识 source，以及
76	// 调用方可接受的规则版本集合。确认在排他锁下重新判断全部前提，绝不使用
77	// 调用方可能修改过的预览状态，而是重新读取并校验来源记录：
78	//
79	//   - current 或 source 为空，或槽已不再指向 current（被并发覆盖、升级
80	//     或另一次恢复抢先提交），返回 *ConflictError。比较只针对槽所指记录，
81	//     即使它已损坏或被删除也不例外，因此损坏/删除的当前标识不会妨碍从
82	//     本槽完好旧记录恢复。
83	//   - 来源必须仍属于该槽、仍能通过内容与父关系校验且版本可接受。其他槽
84	//     的记录、未生效的残留/孤儿记录按 *NotFoundError 拒绝；来源后来被
85	//     删除返回 *NotFoundError，损坏（截断、校验失败、父关系断裂）返回
86	//     *CorruptError，版本不再被接受返回 *VersionRejectedError。来源失效
87	//     时不改选其他记录。
88	//
89	// 成功后产生一条独立的新记录（即使来源就是当前记录），槽指向新记录，
90	// 新记录以来源为父，种子、完整规则、时间片、角色及物品的内容和排列原样
91	// 复制，允许时间片回到来源时刻。旧历史按原保存次序保留，新记录排在最
92	// 前；来源之后仍完好的旧记录可照常读取或分支，已存在的分支不受影响。
93	// 同一 current 上的并发确认、以及确认与普通覆盖或规则升级竞争时，最多
94	// 一个成功。
95	func (a *Archive) ConfirmRecovery(slot string, current, source RecordID, acceptedVersions []string) (RecordInfo, error) {
96		if !validSlotName(slot) {
97			return RecordInfo{}, &NotFoundError{Slot: slot}
98		}
99		if current == "" || source == "" {
100			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "确认恢复必须提供当前记录标识与来源记录标识"}
101		}
102	
103		lock, err := acquireLock(a.dir)
104		if err != nil {
105			return RecordInfo{}, err
106		}
107		defer lock.release()
108	
109		oldPointer, err := a.readSlotPointerLocked(slot)
110		if err != nil {
111			return RecordInfo{}, err
112		}
113		// 乐观并发控制：只有槽仍指向预览时的当前记录才允许确认。当前记录
114		// 本身可能已损坏或被删除——那正是需要恢复的情形——故这里只比较标识，
115		// 不读取它。
116		if oldPointer.Latest != current {
117			return RecordInfo{}, &ConflictError{
118				Slot:   slot,
119				Reason: "槽当前记录已改变，请重新预览后再确认",
120			}
121		}
122	
123		// 来源必须仍在本槽保存次序内：其他槽记录与未生效的孤儿/残留记录
124		// 都不在其中，按记录不存在拒绝。
125		history, err := a.slotHistoryLocked(slot)
126		if err != nil {
127			return RecordInfo{}, err
128		}
129		if err := assertRecordInOrder(history, source); err != nil {
130			return RecordInfo{}, &NotFoundError{Slot: slot, Record: source}
131		}
132	
133		// 重新读取并完整校验来源，不采信调用方带回的任何状态。
134		env, err := a.loadAndVerifyLocked(source)
135		if err != nil {
136			if ce, ok := err.(*CorruptError); ok {
137				ce.Slot = slot
138			}
139			return RecordInfo{}, err
140		}
141		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
142			return RecordInfo{}, &VersionRejectedError{
143				Slot:     slot,
144				Record:   source,
145				Version:  env.State.Rules.Version,
146				Accepted: append([]string(nil), acceptedVersions...),
147			}
148		}
149	
150		// 以选中的来源为父（即使来源就是当前记录，仍保存一条独立新记录），
151		// 种子、完整规则、时间片、角色及物品的内容和排列原样复制，允许时间
152		// 片回到来源时刻。历史承接点用槽指针的当前指向：当前记录已损坏或被
153		// 删除时不能去校验它，但来源之后已经生效的本槽历史仍要原样保留，不
154		// 沿来源的父链截断。沿用共同的组装、落盘与槽指针提交路径。
155		return a.appendSlotRecordLocked(slotSave{
156			slot:          slot,
157			oldPointer:    oldPointer,
158			parent:        source,
159			historyAnchor: oldPointer.Latest,
160			state:         cloneState(env.State),
161		})
162	}
163	
164	// assertRecordInOrder 确认 id 出现在按保存生效次序排列的标识序列中。
165	func assertRecordInOrder(order []RecordID, id RecordID) error {
166		for _, cid := range order {
167			if cid == id {
168				return nil
169			}
170		}
171		return &NotFoundError{Record: id}
172	}
173

