func writeRawRecord(t *testing.T, a *Archive, parent RecordID, first bool, st State) RecordID {
	t.Helper()
	id, err := newRecordID()
	if err != nil {
		t.Fatal(err)
	}
	env := &envelope{
		Format:    archiveFormatVersion,
		ID:        id,
		Parent:    parent,
		SlotFirst: first,
		State:     st,
	}
	env.Checksum = computeChecksum(env)
	if err := writeRecord(a.dir, env); err != nil {
		t.Fatal(err)
	}
	return id
}

