	// 版本拒绝，也不自动把时间改成零。
	if env.State.Time < 0 {
		return nil, &CorruptError{
			Record: id,
			Reason: fmt.Sprintf("记录中的世界时间片不能为负: %d", env.State.Time),
		}
	}
	// 父记录关系必须落到一个真实存在的记录上。
	if env.Parent != "" {
